const request = $json.body ?? $json;

const website = String(request.website || '')
  .trim()
  .toLowerCase();

if (!website) {
  return {
    json: {
      success: false,
      statusCode: 422,
      errorCode: 'MISSING_DOMAIN',
      errorMessage: 'A company website is required for enrichment',
      salesforceLeadId: request.salesforceLeadId || null
    }
  };
}

let domain;

try {
  domain = new URL(website).hostname.replace(/^www\./, '');
} catch {
  domain = website
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split('/')[0];
}

const companyProfiles = {
  'dataharbor-labs.example.com': {
    companyName: 'DataHarbor Labs',
    industry: 'Technology',
    numberOfEmployees: 1200,
    annualRevenue: 180000000,
    headquartersCountry: 'India'
  },

  'insightforge.example.com': {
    companyName: 'InsightForge',
    industry: 'Technology',
    numberOfEmployees: 650,
    annualRevenue: 95000000,
    headquartersCountry: 'India'
  }
};

const profile = companyProfiles[domain];

if (!profile) {
  return {
    json: {
      success: false,
      statusCode: 404,
      errorCode: 'COMPANY_NOT_FOUND',
      errorMessage: `No enrichment profile found for domain: ${domain}`,
      salesforceLeadId: request.salesforceLeadId || null,
      domain
    }
  };
}

return {
  json: {
    success: true,
    statusCode: 200,
    salesforceLeadId: request.salesforceLeadId || null,
    domain,
    enrichmentSource: 'Mock Company Enrichment API',
    enrichedAt: new Date().toISOString(),
    company: profile
  }
};
